CREATE TABLE engine_knowledge(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, scope_hash TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('requirement','observation','workflow','guidance','hypothesis')), status TEXT NOT NULL CHECK(status IN ('approved','verified','provisional','suspect')), text TEXT NOT NULL, source_ref TEXT NOT NULL, evidence_json TEXT NOT NULL, verified_at INTEGER NOT NULL, expires_at INTEGER NOT NULL) STRICT;
CREATE INDEX engine_knowledge_scope ON engine_knowledge(project_id,scope_hash,kind);
CREATE VIRTUAL TABLE engine_knowledge_search USING fts5(entry_id UNINDEXED,project_id UNINDEXED,scope_hash UNINDEXED,text);
CREATE TABLE engine_operational_targets(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, scope_hash TEXT NOT NULL, original_state_id TEXT NOT NULL, current_state_id TEXT NOT NULL, revision_id TEXT, evidence_json TEXT NOT NULL, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_regression_links(task_id TEXT PRIMARY KEY REFERENCES engine_tasks(id), requested_story_id TEXT NOT NULL, reused_plan_id TEXT NOT NULL, equivalence_hash TEXT NOT NULL, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_observed_changes(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES engine_tasks(id), kind TEXT NOT NULL, previous_json TEXT NOT NULL, current_json TEXT NOT NULL, evidence_json TEXT NOT NULL, intent TEXT NOT NULL DEFAULT 'unknown', created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_investigations(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES engine_tasks(id), run_id TEXT NOT NULL, scenario_id TEXT NOT NULL, classification TEXT NOT NULL, confidence TEXT NOT NULL, rationale TEXT NOT NULL, evidence_json TEXT NOT NULL, investigation_run_id TEXT, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_revalidation_schedules(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, task_id TEXT NOT NULL REFERENCES engine_tasks(id), actor TEXT NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN(0,1)), interval_ms INTEGER NOT NULL, next_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(project_id,task_id)) STRICT;
